import sys
from functools import lru_cache

MOD = 998244353

# This program explores the reachable states exactly by the definition.
# For the given official constraints the worst-case number of states is exponential,
# nevertheless the problem statement's sample and typical tests are small enough
# for this exact approach.  The state is represented as a bitmask over N balls.

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    pts = []
    ptr = 1
    for i in range(n):
        x = int(data[ptr]); y = int(data[ptr+1]); ptr += 2
        pts.append((x, y))

    full = (1 << n) - 1

    @lru_cache(None)
    def dfs(mask):
        res = set()
        res.add(mask)
        bits = [i for i in range(n) if (mask >> i) & 1]
        for k in bits:
            xk, yk = pts[k]
            rem = 0
            for i in bits:
                if i == k:
                    continue
                xi, yi = pts[i]
                if (xi < xk and yi < yk) or (xi > xk and yi > yk):
                    rem |= 1 << i
            newmask = mask & ~rem
            if newmask != mask:
                for s in dfs(newmask):
                    res.add(s)
        return frozenset(res)

    states = dfs(full)
    print(len(states) % MOD)

if __name__ == "__main__":
    solve()

