import sys

MOD = 998244353


def solve() -> None:
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = [0] + list(map(int, input().split()))

    children = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        children[A[i]].append(i)

    vis = [0] * (N + 1)
    cycle_nodes = set()
    cycles = []

    for s in range(1, N + 1):
        if vis[s] != 0:
            continue
        path = []
        pos = {}
        cur = s
        while vis[cur] == 0:
            vis[cur] = 1
            pos[cur] = len(path)
            path.append(cur)
            cur = A[cur]

        if vis[cur] == 1:
            cyc = path[pos[cur]:]
            cycles.append(cyc)
            cycle_nodes.update(cyc)

        for v in path:
            vis[v] = 2

    dp = [None] * (N + 1)

    def dfs(u: int) -> None:
        if u in cycle_nodes or dp[u] is not None:
            return

        arr = [1] * (M + 1)
        for v in children[u]:
            if v in cycle_nodes:
                continue
            dfs(v)
            child = dp[v]
            pref = [0] * (M + 1)
            s = 0
            for t in range(1, M + 1):
                s += child[t]
                if s >= MOD:
                    s -= MOD
                pref[t] = s
            for t in range(1, M + 1):
                arr[t] = (arr[t] * pref[t]) % MOD
        dp[u] = arr

    for u in range(1, N + 1):
        if u not in cycle_nodes:
            dfs(u)

    root = [None] * (N + 1)
    for u in range(1, N + 1):
        if u in cycle_nodes:
            arr = [1] * (M + 1)
            for v in children[u]:
                if v in cycle_nodes:
                    continue
                child = dp[v]
                pref = [0] * (M + 1)
                s = 0
                for t in range(1, M + 1):
                    s += child[t]
                    if s >= MOD:
                        s -= MOD
                    pref[t] = s
                for t in range(1, M + 1):
                    arr[t] = (arr[t] * pref[t]) % MOD
            root[u] = arr

    ans = 1
    for cyc in cycles:
        total = 0
        for c in range(1, M + 1):
            prod = 1
            for u in cyc:
                prod = (prod * root[u][c]) % MOD
            total += prod
        ans = (ans * (total % MOD)) % MOD

    print(ans)


if __name__ == "__main__":
    solve()

