import random

def is_contiguous(st):
    n=len(st)
    ones=[i for i,ch in enumerate(st) if ch=='1']
    if not ones: return False
    return all(st[i]=='1' for i in range(ones[0], ones[-1]+1)) and all(st[i]=='0' for i in range(0,ones[0])) and all(st[i]=='0' for i in range(ones[-1]+1,n))

def brute(s):
    n=len(s)
    q=deque([(s,0)])
    seen={s}
    while q:
        st,d=q.popleft()
        if is_contiguous(st):
            return d
        for i in range(n-1):
            t=list(st)
            t[i],t[i+1]=t[i+1],t[i]
            t=''.join(t)
            if t not in seen:
                seen.add(t); q.append((t,d+1))
    return -1

def formula(s):
    n=len(s)
    ones=[i+1 for i,ch in enumerate(s) if ch=='1']
    k=len(ones)
    x=[p - idx for idx,p in enumerate(ones)]
    x=sorted(x)
    med=x[k//2]
    return sum(abs(v-med) for v in x)

