    for i in range(2, m + 1):
        if spf[i] == 0:
            spf[i] = i
            if i * i <= m:
                for j in range(i * i, m + 1, i):
                    if spf[j] == 0:
                        spf[j] = i

    # Grundy number for each value up to max(A)
    grundy = [0] * (m + 1)
    for x in range(2, m + 1):
        y = x
        factors = []
        while y > 1:
            p = spf[y]
