from typing import List

class Fenwick:
    def __init__(self, n: int):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx: int, delta: int) -> None:
        while idx <= self.n:
            self.bit[idx] += delta
            idx += idx & -idx

    def prefix_sum(self, idx: int) -> int:
        s = 0
        while idx > 0:
            s += self.bit[idx]
            idx -= idx & -idx
        return s

    def kth(self, k: int) -> int:
        # smallest index i such that prefix_sum(i) >= k
        idx = 0
        bitmask = 1 << (self.n.bit_length() - 1)
        while bitmask:
            nxt = idx + bitmask
            if nxt <= self.n and self.bit[nxt] < k:
                k -= self.bit[nxt]
                idx = nxt
            bitmask >>= 1
        return idx + 1


class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        edges = set()
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            edges.add((a, b))

        if not edges:
            return 0

        by_left = {}
        for a, b in edges:
            by_left.setdefault(a, []).append((a, b))

        bit = Fenwick(n)
        right_to_ids = {}
        total_active = 0
        reductions = {e: 0 for e in edges}
        bad_total = 0

        for l in range(n, 0, -1):
            for a, b in by_left.get(l, []):
                bit.add(b, 1)
                right_to_ids.setdefault(b, []).append((a, b))
                total_active += 1

            if total_active == 0:
                continue

            min_right = bit.kth(1)
            count_min = bit.prefix_sum(min_right) - bit.prefix_sum(min_right - 1)

            if count_min == 1:
                edge = right_to_ids[min_right][0]
                prefix = bit.prefix_sum(min_right)
                if prefix < total_active:
                    next_right = bit.kth(prefix + 1)
                    delta = next_right - min_right
                else:
                    delta = n - min_right + 1
                reductions[edge] += delta

            bad_total += n - min_right + 1

        total_subarrays = n * (n + 1) // 2
        best_gain = max(reductions.values()) if reductions else 0
        return total_subarrays - bad_total + best_gain

