from functools import lru_cache

def count_lex(grid):
    # grid list of positions coords maybe poset on cells with (r,c) <= (r+1,c) and (r,c+1)
    # For A x B rectangle minus one corner (say top-left removed): cells = all positions except (0,0)
    A,B=3,3
    cells=[(r,c) for r in range(A) for c in range(B) if not (r==0 and c==0)]
    idx={v:i for i,v in enumerate(cells)}
    # dependencies: each cell has predecessors = (r-1,c) if in range and (r,c-1) if in range.
    preds={v:[] for v in cells}
    for v in cells:
        r,c=v
        for u in [(r-1,c),(r,c-1)]:
            if u in idx: preds[v].append(u)
    # But poset includes transitive closure automatically if we just use immediate predecessors.
    # To count linear extensions via DP over subsets, use minimal available elements.
    allmask=(1<<len(cells))-1
    @lru_cache(None)
    def dp(mask):
        if mask==allmask: return 1
        # available are cells not in mask with all preds in mask
        ans=0
        for i,v in enumerate(cells):
            if mask>>i & 1: continue
            ok=True
            for u in preds[v]:
                if not (mask>>idx[u] & 1): ok=False; break
            if ok:
                ans += dp(mask | (1<<i))
        return ans
    return dp(0)
