    N = int(next(it))
    X = int(next(it))
    procs = []
    for _ in range(N):
        A = int(next(it))
        P = int(next(it))
        B = int(next(it))
        Q = int(next(it))
        procs.append((A, P, B, Q))

    def min_cost_for_process(A, P, B, Q, K):
        # If S is at least as efficient as T (P/A <= Q/B), we can assume the number of T-machines
        # is less than A; otherwise the number of S-machines is less than B.
        if P * B <= Q * A:
            best = 10**30
            for y in range(A):
                x = max(0, (K - y * B + A - 1) // A)
                if x * A + y * B >= K:
                    best = min(best, x * P + y * Q)
            return best
        else:
            best = 10**30
            for x in range(B):
                y = max(0, (K - x * A + B - 1) // B)
                if x * A + y * B >= K:
                    best = min(best, x * P + y * Q)
            return best

    def feasible(K):
        total = 0
        for A, P, B, Q in procs:
            total += min_cost_for_process(A, P, B, Q, K)
