from itertools import product

def brute(n,x,y):
    ans=0
    for assign in product(range(x), repeat=n):
        cnt=0
        seen=set()
        for s in assign:
            if s not in seen:
                seen.add(s)
                cnt+=1
        ans += pow(y,cnt,MOD)
    return ans%MOD


def formula(n,x,y):
    K=min(n,x)
    stir=[[0]*(K+1) for _ in range(n+1)]
    stir[0][0]=1
    for i in range(1,n+1):
        for k in range(1,min(i,K)+1):
            stir[i][k]=(stir[i-1][k-1]+k*stir[i-1][k])%MOD
    fact=[1]*(K+1)
    for i in range(1,K+1): fact[i]=fact[i-1]*i%MOD
    inv=[0]*(K+1)
    if K>=1: inv[1]=1
    for i in range(2,K+1):
        inv[i]=MOD-(MOD//i)*inv[MOD%i]%MOD
    comb=[1]*(K+1)
    for k in range(1,K+1):
        comb[k]=comb[k-1]*(x-k+1)%MOD*inv[k]%MOD
    ans=0
    for k in range(1,K+1):
        ans=(ans + comb[k]*stir[n][k]%MOD*fact[k]%MOD*pow(y,k,MOD))%MOD
    return ans

