class Solution:
    MOD = 10**9 + 7

    def countKReducibleNumbers(self, s: str, k: int) -> int:
        # A value c is valid as the popcount of x if x is k-reducible after one operation.
        # So we need c to be (k-1)-reducible (with 1 considered reducible in 0 steps).
        m = len(s)
        valid_popcounts = []
        for c in range(1, m + 1):
            x = c
            steps_left = k - 1
            while x != 1:
                if steps_left == 0:
                    x = 0
                    break
                x = x.bit_count()
                steps_left -= 1
            if x == 1:
                valid_popcounts.append(c)

        # Count numbers < s with exactly c set bits using digit DP.
        # We allow leading zeros, so this counts all numbers from 0 to n-1.
        dp = [[0] * (m + 1) for _ in range(2)]
        dp[1][0] = 1

        for ch in s:
            bit = ord(ch) - 48
            ndp = [[0] * (m + 1) for _ in range(2)]
            for tight in (0, 1):
                for ones in range(m + 1):
                    val = dp[tight][ones]
                    if val == 0:
                        continue
                    limit = bit if tight else 1
                    for d in range(limit + 1):
                        ntight = 1 if tight and d == bit else 0
                        new_ones = ones + d
                        if new_ones <= m:
                            ndp[ntight][new_ones] += val
            dp = ndp

        ans = 0
        for c in valid_popcounts:
            ans += dp[0][c]

        return ans % self.MOD

