import sys

# This is a best-effort implementation that tries to evaluate the
# mountain/valley pattern recursively and maximize the overlap over shifts.
# It is intentionally conservative and avoids any unsupported assumptions.


def paperfold_type(x: int) -> int:
    """Return 1 if x-th crease is mountain, else 0. x is 1-based."""
    if x == 1:
        return 1
    # recursive decomposition: S_n = S_{n-1} M reverse(complement(S_{n-1}))
    # For x in [1, 2^m - 1], we can determine the symbol recursively.
    m = x.bit_length()
    while True:
        p = 1 << (m - 1)
        if x < p:
            m -= 1
            if m <= 0:
                return 1
            continue
        if x == p:
            return 1
        # right half: reverse(complement(previous))
        t = x - p
        return 1 - paperfold_type(p - t)


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    A = list(map(int, data[1:1+n]))

    # We evaluate the intersections for all integer shifts up to the largest
    # relevant offset in the data range. This is still exponential in the worst
    # case, but the problem constraints are too large to do otherwise without the
    # exact closed-form characterization, which is not available here.
    maxv = 0
    L = 1 << 20
    for i in range(1, L - A[-1] + 1):
        cnt = 0
        for a in A:
            if paperfold_type(i + a) == 1:
