import sys


def manacher(s):
    n = len(s)
    odd = [0] * n
    l, r = 0, -1
    for i in range(n):
        k = 1 if i > r else min(odd[l + r - i], r - i + 1)
        while i - k >= 0 and i + k < n and s[i - k] == s[i + k]:
            k += 1
        odd[i] = k
        if i + k - 1 > r:
            l = i - k + 1
            r = i + k - 1

    even = [0] * n
    l, r = 0, -1
    for i in range(n):
        k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
        while i - k - 1 >= 0 and i + k < n and s[i - k - 1] == s[i + k]:
            k += 1
        even[i] = k
        if i + k - 1 > r:
            l = i - k
            r = i + k - 1
    return odd, even


def longest_pal_suffix(s):
    n = len(s)
    if n == 0:
        return 0
    odd, even = manacher(s)
    best = 0
    for i in range(n):
        if i + odd[i] - 1 == n - 1:
            best = max(best, 2 * odd[i] - 1)
        if i + even[i] - 1 == n - 1:
            best = max(best, 2 * even[i])
    return best


