import sys


def nullspace_basis(adj_rows):
    # adj_rows[i] is an integer bitmask of neighbors of vertex i.
    rows = list(adj_rows)
    n = len(rows)
    pivot_cols = []
    r = 0

    for c in range(n):
        pivot = -1
        for i in range(r, n):
            if (rows[i] >> c) & 1:
                pivot = i
                break
        if pivot == -1:
            continue

        rows[r], rows[pivot] = rows[pivot], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]

        pivot_cols.append(c)
        r += 1
        if r == n:
            break

    free_cols = [c for c in range(n) if c not in pivot_cols]
    basis = []
    for free in free_cols:
        vec = 1 << free
        for i, p in enumerate(pivot_cols):
            if (rows[i] >> free) & 1:
                vec |= 1 << p
        basis.append(vec)

    return basis


