    M = int(next(it))

    adj = [[0] * N for _ in range(N)]
    deg = [0] * N

    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u][v] = 1
        adj[v][u] = 1
        deg[u] += 1
        deg[v] += 1

    row_masks = []
    for i in range(N):
        mask = 0
        for j in range(N):
            if adj[i][j]:
                mask |= 1 << j
        row_masks.append(mask)

    basis = nullspace_basis(row_masks)

    if not basis:
        if any(d > 0 for d in deg):
            print("No")
