import random, math

def icbrt(n):
    lo, hi = 0, 1
    while hi**3 <= n:
        hi *= 2
    while lo + 1 < hi:
        mid = (lo + hi)//2
        if mid**3 <= n:
            lo = mid
        else:
            hi = mid
    return lo

def solve(N):
    if N <= 0:
        return None
    lo = icbrt(N)
    x_max = math.isqrt((N//3) + 2) + 2
    # also maybe ensure x_max enough
    for x in range(lo + 1, x_max + 1):
        diff = x*x*x - N
        if diff <= 0:
            continue
        y = icbrt(diff)
        if y > 0 and y*y*y == diff:
            return x, y
    return None

# brute force test small N
for N in range(1, 2000):
    ans = solve(N)
    found = False
    for x in range(1, 200):
        for y in range(1, x):
