from typing import List
from collections import deque

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 0:
            return 0
        m = len(grid[0])

        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        cw = [1, 2, 3, 0]

        # State: (r, c, dir_idx, used_turn, next_expected_value)
        # next_expected_value is either 2 or 0.
        # The current cell already matches the V-pattern; the next cell must match next_expected_value.
        best = {}
        q = deque()
        ans = 0

        for r in range(n):
            for c, val in enumerate(grid[r]):
                if val != 1:
                    continue
                ans = max(ans, 1)
                for d, (dr, dc) in enumerate(dirs):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < m and grid[rr][cc] == 2:
                        state = (rr, cc, d, False, 0)
                        if state not in best or 2 > best[state]:
                            best[state] = 2
                            q.append(state)

        while q:
            r, c, d, used, need = q.popleft()
            length = best[(r, c, d, used, need)]
            ans = max(ans, length)

            dr, dc = dirs[d]
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m and grid[rr][cc] == need:
                new_need = 0 if need == 2 else 2
                state = (rr, cc, d, used, new_need)
                new_len = length + 1
                if state not in best or new_len > best[state]:
                    best[state] = new_len
                    q.append(state)

            if not used:
                nd = cw[d]
                dr2, dc2 = dirs[nd]
                rr, cc = r + dr2, c + dc2
                if 0 <= rr < n and 0 <= cc < m and grid[rr][cc] == need:
                    new_need = 0 if need == 2 else 2
                    state = (rr, cc, nd, True, new_need)
                    new_len = length + 1
                    if state not in best or new_len > best[state]:
                        best[state] = new_len
                        q.append(state)

        return ans

