from math import factorial
from typing import List


class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def count_remaining(odd_rem: int, even_rem: int, start_odd: bool) -> int:
            m = odd_rem + even_rem
            if m == 0:
                return 1
            if start_odd:
                if odd_rem == (m + 1) // 2 and even_rem == m // 2:
                    return factorial(odd_rem) * factorial(even_rem)
            else:
                if even_rem == (m + 1) // 2 and odd_rem == m // 2:
                    return factorial(odd_rem) * factorial(even_rem)
            return 0

        total_odd = (n + 1) // 2
        total_even = n // 2
        total = count_remaining(total_odd, total_even, True) + count_remaining(total_odd, total_even, False)
        if k > total:
            return []

        used = [False] * (n + 1)
        ans = []
        last_parity = None  # None for empty prefix; 1 for odd, 0 for even

        for _ in range(n):
            for v in range(1, n + 1):
                if used[v]:
                    continue
                if last_parity is not None and (v % 2 == last_parity):
                    continue

                used[v] = True
                odd_rem = sum(1 for x in range(1, n + 1) if (not used[x]) and x % 2 == 1)
                even_rem = sum(1 for x in range(1, n + 1) if (not used[x]) and x % 2 == 0)

                # After choosing v, the next value must have opposite parity.
                next_need_odd = (v % 2 == 0)
                cnt = count_remaining(odd_rem, even_rem, next_need_odd)
                used[v] = False

                if cnt == 0:
                    continue
                if k <= cnt:
                    ans.append(v)
                    used[v] = True
                    last_parity = v % 2
                    break
                k -= cnt
            else:
                return []

        return ans

