    if not data:
        return
    n = data[0]
    A = data[1:1+n]
    B = data[1+n:1+2*n]
    C = data[1+2*n:1+3*n]

    W = sum(a * c for a, c in zip(A, C))
    deltas = []
    pos = []
    for i in range(n):
        if A[i] != B[i]:
            if A[i] == 0:
                deltas.append(C[i])
                pos.append(C[i])
            else:
                deltas.append(-C[i])

