        extras = [C[i] for i in range(n) if A[i] == 1 and B[i] == 1]
        extras.sort(reverse=True)
        total_pos = sum(pos)
        for c in extras:
            if c >= total_pos:
                deltas.extend([-c, c])
                total_pos += c

    deltas.sort()
    cur = W
    ans = 0
    for d in deltas:
        cur += d
        ans += cur
    print(ans)


