class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        # Base case: 1-digit palindromes divisible by k.
        if n == 1:
            for d in range(9, 0, -1):
                if d % k == 0:
                    return str(d)
            return "0"

        # half_len = number of digits in the first half (including the middle digit if odd)
        half_len = (n + 1) // 2

        # weights[i] is the contribution of digit i in the first half (including midpoint)
        # to the total value modulo k.
        weights = []
        if n % 2 == 0:
            # even length: 2*half_len
            for i in range(half_len):
                w = (pow(10, n - 1 - i, k) + pow(10, i, k)) % k
                weights.append(w)
        else:
            # odd length: 2*half_len - 1
            for i in range(half_len - 1):
                w = (pow(10, n - 1 - i, k) + pow(10, i, k)) % k
                weights.append(w)
            weights.append(pow(10, half_len - 1, k))

        L = len(weights)

        # suffix_possible[i][r] = can we choose digits from positions i..L-1
        # so that their weighted sum modulo k is exactly r?
        suffix_possible = [[False] * k for _ in range(L + 1)]
        suffix_possible[L][0] = True
        for i in range(L - 1, -1, -1):
            digits = range(1, 10) if i == 0 else range(10)
            for r in range(k):
                for d in digits:
                    if suffix_possible[i + 1][(r - d * weights[i]) % k]:
                        suffix_possible[i][r] = True
                        break

        chosen = []
        acc = 0
        for i in range(L):
            digits = range(9, 0, -1) if i == 0 else range(9, -1, -1)
            for d in digits:
                new_acc = (acc + d * weights[i]) % k
                # The remaining suffix must still be able to make total sum 0.
                if suffix_possible[i + 1][(-new_acc) % k]:
                    chosen.append(d)
                    acc = new_acc
                    break
            else:
                # This should never happen for valid inputs, because a solution exists.
                return "0"

        if acc != 0:
            return "0"

        if n % 2 == 0:
            palindrome = chosen + chosen[::-1]
        else:
            palindrome = chosen + chosen[:-1][::-1]

        return ''.join(map(str, palindrome))

