class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Fast path: if the whole array is already non-decreasing,
        # every subarray is valid.
        if all(nums[i] <= nums[i + 1] for i in range(n - 1)):
            return n * (n + 1) // 2

        ans = 0
        for l in range(n):
            pref_max = -10**30
            cost = 0
            for r in range(l, n):
                x = nums[r]
                if x < pref_max:
                    cost += pref_max - x
                    if cost > k:
                        break
                else:
                    pref_max = x
                ans += 1
        return ans

