from functools import cmp_to_key


def cmp(a, b):
    A1, B1 = a
    A2, B2 = b
    if A1 == 1 and A2 == 1:
        return 0
    if A1 == 1:
        return -1
    if A2 == 1:
        return 1
    lhs = B1 * (A2 - 1)
    rhs = B2 * (A1 - 1)
    if lhs > rhs:
        return -1
    if lhs < rhs:
        return 1
    return 0


