import random, itertools

def brute(N, K, funcs):
    best=-1
    for perm in itertools.permutations(range(N), K):
        x=1
        for idx in perm:
            a,b=funcs[idx]
            x=a*x+b
        best=max(best,x)
    return best

def dp_sorted(N,K,funcs):
    arr=[]
    for i,(a,b) in enumerate(funcs):
        if a==1:
            arr.append((float('inf'),i,a,b))
        else:
            arr.append((b/(a-1),i,a,b))
    arr.sort(key=lambda x:x[0], reverse=True)
    dp=[-1]*(K+1)
    dp[0]=1
    for _,_,a,b in arr:
        for t in range(min(K, len(arr)),0,-1):
            if dp[t-1] >= 0:
                val=a*dp[t-1]+b
                if val>dp[t]: dp[t]=val
    return dp[K]

