class Solution:
    def makeStringGood(self, s: str) -> int:
        freq = [0] * 26
        for ch in s:
            freq[ord(ch) - ord('a')] += 1

        n = len(s)
        ans = n

        # Try every possible target frequency
        for k in range(n + 1):
            surplus = 0
            deficit = 0
            for c in freq:
                if c > k:
                    surplus += c - k
                elif c < k:
                    deficit += k - c

            # A character change can simultaneously fix one surplus and one deficit.
            # So the best we can do is balance the two sides.
            ans = min(ans, max(surplus, deficit))

        return ans

