                new_h2 = hand2
                new_table = add_card(table, x)
                if not win(1 - turn, new_h1, new_h2, new_table):
                    return True
                for y in sorted(v for v in table if v < x):
                    nh1 = add_card(remove_card(hand1, x), y)
