import random

def formula(arr):
    b=sorted(arr)
    s=0
    i=0; j=len(b)-1
    while i<j:
        s += b[j]-b[i]
        i += 1; j -= 1
    return s

# brute DP for all intervals, correct
from functools import lru_cache

def brute(arr):
    n=len(arr)
    @lru_cache(None)
    def dp(i,j):
        if i>j: return 0
        if i==j: return 0
        best=0
        # skip first element if odd remaining length
        if (j-i+1)%2==1:
            best=max(best, dp(i+1,j))
        for k in range(i+1,j+1):
            if (k-i)%2==1:
                val=abs(arr[i]-arr[k])+dp(i+1,k-1)+dp(k+1,j)
                best=max(best,val)
        return best
    return dp(0,n-1)

for n in range(2,11):
    for _ in range(1000):
        arr=[random.randint(1,10) for _ in range(n)]
        f=formula(arr)
        b=brute(arr)
        if f!=b:
            print('mismatch',n,arr,'formula',f,'brute',b)
            raise SystemExit
print('ok')

