import sys

MOD = 998244353


class DSU:
    __slots__ = ('p', 'sz')

    def __init__(self, n: int):
        self.p = list(range(n))
        self.sz = [1] * n

    def find(self, x: int) -> int:
        p = self.p
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x

    def union(self, a: int, b: int) -> None:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return
        if self.sz[ra] < self.sz[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        self.sz[ra] += self.sz[rb]


def solve() -> None:
    input = sys.stdin.readline
    T = int(input())
    out = []

    for _ in range(T):
        H, W = map(int, input().split())
        grid = [input().strip() for _ in range(H)]

        rowA = [0] * H
        colA = [0] * W
        for i in range(H):
            s = grid[i]
            for j, ch in enumerate(s):
                if ch == 'A':
                    rowA[i] += 1
                    colA[j] += 1

        # Necessary parity condition: every row / column must contain an even number of A's.
        if any(x % 2 for x in rowA) or any(x % 2 for x in colA):
            out.append('0')
            continue

        # Build bipartite graph on rows and columns; B-cells are edges.
        dsu = DSU(H + W)
        for i in range(H):
            for j, ch in enumerate(grid[i]):
                if ch == 'B':
                    dsu.union(i, H + j)

        roots = set()
        for v in range(H + W):
            roots.add(dsu.find(v))

        out.append(str(pow(2, len(roots), MOD)))

    sys.stdout.write('\n'.join(out))


if __name__ == "__main__":
    solve()

