from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        star1 = p.find('*')
        star2 = p.find('*', star1 + 1)
        A = p[:star1]
        B = p[star1 + 1:star2]
        C = p[star2 + 1:]

        def occurrences(text: str, pat: str):
            if not pat:
                return []
            m = len(pat)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            res = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = pi[j - 1]
            return res

        # Middle literal exists: choose a B occurrence and optimize A/C around it.
        if B:
            apos = occurrences(s, A)
            bpos = occurrences(s, B)
            cpos = occurrences(s, C)
            best = 10**18

            for b in bpos:
                if A:
                    ends = [x + len(A) - 1 for x in apos]
                    idx = bisect_right(ends, b - 1)
                    if idx == 0:
                        continue
                    end_a = ends[idx - 1]
                    start_a = end_a - len(A) + 1
                else:
                    start_a = b

                if C:
                    idx = bisect_left(cpos, b + len(B))
                    if idx >= len(cpos):
                        continue
                    start_c = cpos[idx]
                else:
                    start_c = b + len(B)

                length = start_c + len(C) - start_a
                if length < best:
                    best = length

            return -1 if best == 10**18 else best

        # Middle literal is empty: pattern becomes A* C (or *C / A* / **)
        if not A and not C:
            return 0
        if not A:
            return len(C) if C in s else -1
        if not C:
            return len(A) if A in s else -1

        apos = occurrences(s, A)
        cpos = occurrences(s, C)
        best = 10**18
        for a in apos:
            idx = bisect_left(cpos, a + len(A))
            if idx < len(cpos):
                length = cpos[idx] + len(C) - a
                if length < best:
                    best = length
        return -1 if best == 10**18 else best

