        dp[0].add(0)
        used = 0
        for v in arr:
            used += 1
            upper = min(limit, used)
            for s in range(upper, 0, -1):
                prev = dp[s - 1]
                for x in list(prev):
                    dp[s].add(x ^ v)
        return dp

    left = build_subset_xors(left_arr, K)
    right = build_subset_xors(right_arr, K)

    class Trie:
        def __init__(self):
            self.root = {}

        def add(self, x):
            node = self.root
            for b in range(59, -1, -1):
                bit = (x >> b) & 1
                nxt = node.get(bit)
                if nxt is None:
                    nxt = {}
                    node[bit] = nxt
                node = nxt

        def query_max_xor(self, x):
            node = self.root
            res = 0
            for b in range(59, -1, -1):
                bit = (x >> b) & 1
                other = 1 - bit
                if other in node:
                    res |= 1 << b
                    node = node[other]
                else:
                    node = node[bit]
            return res

