    for s in range(K + 1):
        t = K - s
        if t < 0:
            continue
        ls = left[s]
        rs = right[t]
        if not ls or not rs:
            continue

        # Small cases: direct brute force is faster and simpler.
        if len(ls) * len(rs) <= 200000:
            for x in ls:
                for y in rs:
                    val = x ^ y
                    if val > ans:
                        ans = val
        else:
