def treap_sol(N, P):
    class Node:
        __slots__ = ('v','l','r','p','sz')
        def __init__(self,v):
            self.v=v; self.l=None; self.r=None; self.p=random.randrange(1<<30); self.sz=1
    def upd(t):
        if t: t.sz = 1 + (t.l.sz if t.l else 0)+(t.r.sz if t.r else 0)
