        if not t: return None,None
        if (t.l.sz if t.l else 0) >= k:
            a,b = split(t.l,k)
            t.l = b; upd(t)
            return a,t
        a,b = split(t.r, k - (t.l.sz if t.l else 0) - 1)
        t.r = a; upd(t)
        return t,b
    def merge(a,b):
        if not a or not b: return a or b
        if a.p > b.p:
            a.r = merge(a.r,b)
            upd(a)
            return a
        b.l = merge(a,b.l)
        upd(b)
        return b
    root=None
    for i,p in enumerate(P,1):
        left,right = split(root,p-1)
        node=Node(i)
        root = merge(left,node)
        root = merge(root,right)
