import sys


def can_make(s: str, t: str, k: int) -> bool:
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False

    # To reduce the number of states, keep the band where |i-j| <= k.
    # For row i, only columns j in [i-k, i+k] can still be within k edits.
    if n < m:
        s, t = t, s
        n, m = m, n

    INF = 10**18
    # Row 0: transforming empty string to t[:j] needs exactly j insertions.
    prev = {j: j for j in range(min(m, k) + 1)}

    for i in range(1, n + 1):
        left = max(0, i - k)
        right = min(m, i + k)
        curr = {}

        for j in range(left, right + 1):
            best = INF

            # Delete one char from s[:i]
            if j in prev:
                best = min(best, prev[j] + 1)

            # Insert one char into current prefix (using already-computed current row)
            if j - 1 >= left and (j - 1) in curr:
                best = min(best, curr[j - 1] + 1)

            # Replace one char (or match)
            if j - 1 >= 0:
                prev_val = prev.get(j - 1, INF)
                cost = 0 if s[i - 1] == t[j - 1] else 1
                best = min(best, prev_val + cost)

            if best < INF:
                curr[j] = best

        if not curr:
            return False
        prev = curr

    return m in prev and prev[m] <= k


