from bisect import bisect_right


def floor_root_k(n, k):
    lo, hi = 0, 1
    while hi ** k <= n:
        hi *= 2
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid
    return lo


def count_primes_upto(limit):
    count = 0
    for x in range(2, limit + 1):
        if x == 2:
            count += 1
            continue
        if x % 2 == 0:
            continue
        is_prime = True
        d = 3
        while d * d <= x:
            if x % d == 0:
                is_prime = False
                break
            d += 2
        if is_prime:
            count += 1
    return count


def sieve(limit):
    if limit < 2:
        return []
    is_prime = bytearray(b'\x01') * (limit + 1)
    is_prime[0:2] = b'\x00\x00'
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            start = i * i
            step = i
            is_prime[start:limit + 1:step] = b'\x00' * (((limit - start) // step) + 1)
    return [i for i in range(2, limit + 1) if is_prime[i]]


