from itertools import permutations


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N = next(it)

    G = [[False] * N for _ in range(N)]
    M_G = next(it)
    for _ in range(M_G):
        u = next(it) - 1
        v = next(it) - 1
        G[u][v] = G[v][u] = True

    H = [[False] * N for _ in range(N)]
    M_H = next(it)
    for _ in range(M_H):
        u = next(it) - 1
        v = next(it) - 1
        H[u][v] = H[v][u] = True

    A = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(i + 1, N):
            A[i][j] = A[j][i] = next(it)

    ans = 10**18
    for perm in permutations(range(N)):
        cost = 0
        for i in range(N):
            pi = perm[i]
            for j in range(i + 1, N):
                pj = perm[j]
                if G[i][j] != H[pi][pj]:
                    cost += A[pi][pj]
        if cost < ans:
            ans = cost

    print(ans)


if __name__ == "__main__":
    solve()

