from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        class Line:
            __slots__ = ("m", "b")
            def __init__(self, m: int, b: int):
                self.m = m
                self.b = b

        def eval_line(line: Line, x: int) -> int:
            return line.m * x + line.b

        class LiChao:
            def __init__(self, n: int):
                self.n = n
                self.seg = [None] * (4 * n + 5)

            def add_line(self, line: Line, idx: int = 1, l: int = 0, r: int = None):
                if r is None:
                    r = self.n - 1
                if self.seg[idx] is None:
                    self.seg[idx] = line
                    return
                if l == r:
                    return
                mid = (l + r) // 2
                cur = self.seg[idx]
                if eval_line(line, mid) > eval_line(cur, mid):
                    self.seg[idx], line = line, cur
                if eval_line(line, l) > eval_line(self.seg[idx], l):
                    self.add_line(line, idx * 2, l, mid)
                elif eval_line(line, r) > eval_line(self.seg[idx], r):
                    self.add_line(line, idx * 2 + 1, mid + 1, r)

            def query(self, x: int, idx: int = 1, l: int = 0, r: int = None) -> int:
                if r is None:
                    r = self.n - 1
                res = -10**30
                cur = self.seg[idx]
                if cur is not None:
                    res = eval_line(cur, x)
                if l == r:
                    return res
                mid = (l + r) // 2
                if x <= mid:
                    return max(res, self.query(x, idx * 2, l, mid))
                return max(res, self.query(x, idx * 2 + 1, mid + 1, r))

        tree = LiChao(n)
        tree.add_line(Line(nums[0], 0))
        dp = [0] * n
        for i in range(1, n):
            dp[i] = tree.query(i)
            tree.add_line(Line(nums[i], dp[i] - i * nums[i]))
        return dp[-1]

