class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = {}
        for x in nums:
            freq[x] = freq.get(x, 0) + 1

        ans = float('-inf')
        for x, count in freq.items():
            if (total - x) % 2 != 0:
                continue
            y = (total - x) // 2

            if x == y:
                if count >= 2:
                    ans = max(ans, x)
            elif y in freq:
                ans = max(ans, x)

        return int(ans)

