from collections import Counter

def brute(nums):
    n=len(nums)
    total=sum(nums)
    cand=[]
    for i in range(n):
        for j in range(n):
            if i==j: continue
            # j is sum index, i is outlier
            if total == nums[i] + 2*nums[j]:
                cand.append(nums[i])
    return max(cand) if cand else None

# formula

def formula(nums):
    total=sum(nums)
    freq=Counter(nums)
    ans=-10**18
    for x,c in freq.items():
        if (total-x)%2!=0: continue
        y=(total-x)//2
        if x==y:
            if c>=2:
                ans=max(ans,x)
        elif y in freq:
            ans=max(ans,x)
    return ans if ans!=-10**18 else None

