        s = list(str(x))
        for i in range(d):
            digit = int(s[i])
            if digit < 9:
                t = s[:]
                t[i] = str(digit + 1)
                y = int(''.join(t))
                if len(str(y)) == d:
                    yield y
            if digit > 0:
                if i == 0 and digit == 1:
                    continue
                t = s[:]
                t[i] = str(digit - 1)
                y = int(''.join(t))
                if len(str(y)) == d:
                    yield y

