from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        MOD = (1 << 61) - 1
        BASE = 911382629

        pref = [0] * (n + 1)
        power = [1] * (n + 1)

        for i, value in enumerate(nums):
            pref[i + 1] = (pref[i] * BASE + (value + 1)) % MOD
            power[i + 1] = (power[i] * BASE) % MOD

        def segment_hash(l: int, r: int) -> int:
            return (pref[r] - pref[l] * power[r - l]) % MOD

        def equal(a: int, b: int, length: int) -> bool:
            return segment_hash(a, a + length) == segment_hash(b, b + length)

        ans = 0
        for i in range(1, n - 1):
            for j in range(i + 1, n):
                middle = j - i
                if middle >= i and equal(0, i, i):
                    ans += 1
                    continue
                if middle <= n - j and equal(i, j, middle):
                    ans += 1
        return ans

