from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        if n <= 1:
            return 0

        # Check whether even the full graph allows all nodes to reach node 0.
        # In the reversed graph, this means 0 can reach every node.
        rev = [[] for _ in range(n)]
        for a, b, _ in edges:
            rev[b].append(a)

        seen = [False] * n
        seen[0] = True
        stack = [0]
        while stack:
            u = stack.pop()
            for v in rev[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)

        if not all(seen):
            return -1

        weights = sorted({w for _, _, w in edges})
        lo, hi = 0, len(weights) - 1
        ans = -1

        while lo <= hi:
            mid = (lo + hi) // 2
            limit = weights[mid]

            seen = [False] * n
            seen[0] = True
            stack = [0]
            while stack:
                u = stack.pop()
                for a, b, w in edges:
                    if w <= limit and b == u and not seen[a]:
                        seen[a] = True
                        stack.append(a)

            if all(seen):
                ans = limit
                hi = mid - 1
            else:
                lo = mid + 1

        return ans

