import random

def reach_to_zero(n, edges):
    rev=[[] for _ in range(n)]
    for a,b,w in edges: rev[b].append(a)
    stack=[0]; seen={0}
    while stack:
        u=stack.pop()
        for v in rev[u]:
            if v not in seen:
                seen.add(v); stack.append(v)
    return len(seen)==n

