import sys


def solve():
    input = sys.stdin.readline
    N, W = map(int, input().split())
    cols = [[] for _ in range(W)]
    for i in range(1, N + 1):
        x, y = map(int, input().split())
        cols[x - 1].append((y, i))

    # Sort each column by y, bottom-to-top.
    for c in cols:
        c.sort()

    # Initial full-bottom condition (before the first movement).
    initial_full = True
    for x in range(W):
        if not cols[x] or cols[x][0][0] != 1:
            initial_full = False
            break

    # Rank of each block in its column, bottom-to-top.
    rank = {}
    col_count = [len(c) for c in cols]
    for x in range(W):
        for r, (y, bid) in enumerate(cols[x], 1):
            rank[bid] = r

    # State right after the first move (time 1.5), before any further clears.
    # If the whole bottom row is occupied at time 0, the bottom blocks are removed first.
    first_after = {}
    after_count = col_count[:]
    if initial_full:
        for x in range(W):
            if col_count[x] > 0:
                for r, (y, bid) in enumerate(cols[x][1:], 1):
                    first_after[bid] = r
                after_count[x] = col_count[x] - 1
    else:
        for x in range(W):
            for r, (y, bid) in enumerate(cols[x], 1):
                first_after[bid] = r

    # If some column is empty, no clear can ever happen again.
    all_nonempty = all(v > 0 for v in after_count)

    Q = int(input())
    out = []
    for _ in range(Q):
        T, A = map(int, input().split())

        if T == 1:
            # After the first move, no further clear has happened yet.
            out.append("Yes" if A in first_after else "No")
            continue

        if not all_nonempty:
            # No future clear is possible.
            out.append("Yes" if A in first_after else "No")
            continue

        # After time 1, the clear process is: as long as all columns are non-empty,
        # each step removes the current bottom block from every column.
        # So after the first clear, all surviving blocks have their rank reduced by 1.
        # The number of additional clears before time T is min(T-1, min(after_count)).
        extra = min(T - 1, min(after_count))
        if A not in first_after:
            out.append("No")
            continue
        out.append("Yes" if first_after[A] > extra else "No")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    solve()

