class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        total_ones = s.count('1')
        t = '1' + s + '1'
        answer = total_ones
        n = len(t)

        i = 1
        while i < n - 1:
            if t[i] == '1':
                j = i
                while j < n - 1 and t[j] == '1':
                    j += 1

                # Only consider 1-blocks that are surrounded by 0s in the augmented string
                if t[i - 1] == '0' and t[j] == '0':
                    left_zero = 0
                    k = i - 1
                    while k >= 0 and t[k] == '0':
                        left_zero += 1
                        k -= 1

                    right_zero = 0
                    k = j
                    while k < n and t[k] == '0':
                        right_zero += 1
                        k += 1

                    answer = max(answer, total_ones + left_zero + right_zero)

                i = j
            else:
                i += 1

        return answer

