        vowels = set('aeiou')
        n = len(word)
        ans = 0

        for left in range(n):
            counts = [0] * 5
            consonants = 0

            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    counts['aeiou'.index(ch)] += 1
                else:
                    consonants += 1
                    if consonants > k:
