            ys = {p[1] for p in ps}

            if len(xs) != 2 or len(ys) != 2:
                continue

            x1, x2 = sorted(xs)
            y1, y2 = sorted(ys)
            corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}

            if set(tuple(p) for p in ps) != corners:
                continue

            valid = True
            for p in points:
                tp = tuple(p)
                if tp in corners:
                    continue
                x, y = p
                if x1 <= x <= x2 and y1 <= y <= y2:
                    valid = False
                    break

            if valid:
                area = (x2 - x1) * (y2 - y1)
                if area > best:
                    best = area

        return best if best > 0 else -1

