import random

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        n = len(original)
        offset = 0
        low = bounds[0][0]
        high = bounds[0][1]
        for i in range(1, n):
            offset += original[i] - original[i - 1]
            low_i = bounds[i][0] - offset
            high_i = bounds[i][1] - offset
            low = max(low, low_i)
            high = min(high, high_i)
            if low > high:
                return 0
        return high - low + 1


